cf=D+'vcache_%s.json'%ph; C=json.load(open(cf)) if os.path.exists(cf) else {}
def ask(t):
    if t in C: return t,C[t]
    r=subprocess.run(['claude','-p','--model','sonnet','--setting-sources','','--strict-mcp-config','--disable-slash-commands','--tools','','--no-session-persistence','--system-prompt',SP,'CARD QUESTION:\n'+t],capture_output=True,text=True,timeout=120,cwd='/tmp',stdin=subprocess.DEVNULL)
    return t,r.stdout.strip().upper()
def run(rows):
    with T(8) as ex:
